function createStore(reducer, preloadedState, enhancer) {
  if (typeof enhancer === 'function') return enhancer(createStore)(reducer, preloadedState);
  const freeze = (v) => (v && typeof v === 'object' ? Object.freeze(v) : v);
  let state = freeze(preloadedState);
  let listeners = [];

  const getState = () => state;
  const dispatch = (action) => {
    if (!action || typeof action !== 'object' || Array.isArray(action) || !('type' in action)) {
      throw new Error('Actions must be plain objects with a type');
    }
    state = freeze(reducer(state, action));
    for (const l of [...listeners]) l();
    return action;
  };
  const subscribe = (listener) => {
    listeners.push(listener);
    return () => { listeners = listeners.filter((l) => l !== listener); };
  };

  dispatch({ type: '@@INIT' });
  return { getState, dispatch, subscribe };
}

function combineReducers(reducers) {
  return (state = {}, action) => {
    const next = {};
    for (const key of Object.keys(reducers)) next[key] = reducers[key](state[key], action);
    return next;
  };
}

function applyMiddleware(...middlewares) {
  return (create) => (reducer, preloadedState) => {
    const store = create(reducer, preloadedState);
    let dispatch = () => { throw new Error('Dispatching while building middleware'); };
    const api = { getState: store.getState, dispatch: (action) => dispatch(action) };
    dispatch = middlewares.map((m) => m(api)).reduceRight((next, m) => m(next), store.dispatch);
    return { ...store, dispatch };
  };
}

