const targetMap = new WeakMap();
const proxyCache = new WeakMap();
let activeEffect = null;

function depsFor(target, key) {
  let byKey = targetMap.get(target);
  if (!byKey) targetMap.set(target, (byKey = new Map()));
  let set = byKey.get(key);
  if (!set) byKey.set(key, (set = new Set()));
  return set;
}

function track(target, key) {
  if (!activeEffect) return;
  const set = depsFor(target, key);
  set.add(activeEffect);
  activeEffect.deps.push(set);
}

function trigger(target, key) {
  const set = targetMap.get(target)?.get(key);
  if (!set) return;
  for (const e of [...set]) (e.scheduler ? e.scheduler() : e());
}

function effect(fn, scheduler) {
  const runner = () => {
    for (const set of runner.deps) set.delete(runner); // cleanup old deps
    runner.deps = [];
    const prev = activeEffect;
    activeEffect = runner;
    try { return fn(); } finally { activeEffect = prev; }
  };
  runner.deps = [];
  runner.scheduler = scheduler;
  return runner;
}

function reactive(obj) {
  if (proxyCache.has(obj)) return proxyCache.get(obj);
  const proxy = new Proxy(obj, {
    get(t, k, r) {
      const v = Reflect.get(t, k, r);
      track(t, k);
      return v !== null && typeof v === 'object' ? reactive(v) : v;
    },
    set(t, k, v, r) {
      const old = t[k];
      const ok = Reflect.set(t, k, v, r);
      if (!Object.is(old, v)) trigger(t, k);
      return ok;
    },
  });
  proxyCache.set(obj, proxy);
  return proxy;
}

function watchEffect(fn) {
  const runner = effect(fn);
  runner();
  return runner;
}

function computed(getter) {
  let dirty = true;
  let value;
  const holder = {};
  const runner = effect(getter, () => {
    if (!dirty) {
      dirty = true;
      trigger(holder, 'value');
    }
  });
  Object.defineProperty(holder, 'value', {
    get() {
      track(holder, 'value');
      if (dirty) {
        value = runner();
        dirty = false;
      }
      return value;
    },
  });
  return holder;
}

