h(type, props, ...children):
  kids = children flattened, without null/false/undefined, numbers -> strings
  return { type, props: props || {}, children: kids }

diff(a, b, path = []):
  if a is a string or b is a string or a.type != b.type:
    return a === b ? [] : [{ type: 'REPLACE', path, node: b }]
  patches = []
  set = props in b that are new or different; remove = props of a missing in b
  if set or remove not empty -> push { type: 'PROPS', path, set, remove }
  for i < min(lenA, lenB): patches += diff(a.children[i], b.children[i], [...path, i])
  for i from lenA to lenB - 1: push { type: 'INSERT', path, index: i, node: b.children[i] }
  for i from lenA - 1 down to lenB: push { type: 'REMOVE', path, index: i }
  return patches

patch(node, patches): copy = deep copy; apply each patch at its path; return copy

