function h(type, props, ...children) {
  const kids = children
    .flat(Infinity)
    .filter((c) => c !== null && c !== undefined && c !== false)
    .map((c) => (typeof c === 'object' ? c : String(c)));
  return { type, props: props || {}, children: kids };
}

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

function renderToString(node) {
  if (typeof node === 'string') return esc(node);
  const attrs = Object.entries(node.props).map(([k, v]) => ' ' + k + '="' + esc(v) + '"').join('');
  return '<' + node.type + attrs + '>' + node.children.map(renderToString).join('') + '</' + node.type + '>';
}

function diff(a, b, path = []) {
  if (typeof a === 'string' || typeof b === 'string' || a.type !== b.type) {
    return a === b ? [] : [{ type: 'REPLACE', path, node: b }];
  }
  const patches = [];
  const set = {};
  const remove = [];
  for (const [k, v] of Object.entries(b.props)) if (a.props[k] !== v) set[k] = v;
  for (const k of Object.keys(a.props)) if (!(k in b.props)) remove.push(k);
  if (Object.keys(set).length || remove.length) patches.push({ type: 'PROPS', path, set, remove });

  const la = a.children.length;
  const lb = b.children.length;
  for (let i = 0; i < Math.min(la, lb); i++) patches.push(...diff(a.children[i], b.children[i], [...path, i]));
  for (let i = la; i < lb; i++) patches.push({ type: 'INSERT', path, index: i, node: b.children[i] });
  for (let i = la - 1; i >= lb; i--) patches.push({ type: 'REMOVE', path, index: i });
  return patches;
}

function patch(node, patches) {
  let root = structuredClone(node);
  for (const p of patches) {
    if (p.type === 'REPLACE' && p.path.length === 0) { root = structuredClone(p.node); continue; }
    const steps = p.type === 'REPLACE' ? p.path.slice(0, -1) : p.path;
    let target = root;
    for (const i of steps) target = target.children[i];
    if (p.type === 'REPLACE') target.children[p.path[p.path.length - 1]] = structuredClone(p.node);
    if (p.type === 'PROPS') {
      Object.assign(target.props, p.set);
      for (const k of p.remove) delete target.props[k];
    }
    if (p.type === 'INSERT') target.children.splice(p.index, 0, structuredClone(p.node));
    if (p.type === 'REMOVE') target.children.splice(p.index, 1);
  }
  return root;
}

