class Observable(subscribeFn):
  subscribe(observer):
    obs = typeof observer == 'function' ? { next: observer } : observer
    closed = false; teardown = null
    close() { if closed return; closed = true; teardown && teardown() }
    safe = {
      next(v)     { if !closed: obs.next?.(v) }
      error(e)    { if !closed: closed... call obs.error?.(e); run teardown }
      complete()  { if !closed: call obs.complete?.(); run teardown }
    }
    try teardown = subscribeFn(safe) catch e -> safe.error(e)
    if already closed -> run teardown now
    return { unsubscribe: close }

  map(fn)    = new Observable(s => this.subscribe({ next: v => s.next(fn(v)), error: s.error, complete: s.complete }).unsubscribe)
  filter(fn) = same, but next only if fn(v)
  take(n)    = new Observable(s => { count; sub = this.subscribe({ next: v => { s.next(v); if ++count >= n: s.complete(); sub?.unsubscribe() } ... }) ... })

