class Observable {
  constructor(subscribeFn) {
    this.subscribeFn = subscribeFn;
  }

  subscribe(observer = {}) {
    const obs = typeof observer === 'function' ? { next: observer } : observer;
    let closed = false;
    let teardown = null;
    const cleanup = () => {
      if (typeof teardown === 'function') { const t = teardown; teardown = null; t(); }
    };
    const safe = {
      next: (v) => { if (!closed) obs.next?.(v); },
      error: (e) => { if (closed) return; closed = true; obs.error?.(e); cleanup(); },
      complete: () => { if (closed) return; closed = true; obs.complete?.(); cleanup(); },
      get closed() { return closed; },
    };
    try {
      teardown = this.subscribeFn(safe) ?? null;
    } catch (e) {
      safe.error(e);
    }
    if (closed) cleanup(); // completed during subscribeFn: tear down at once
    return {
      unsubscribe() {
        if (closed) return;
        closed = true;
        cleanup();
      },
    };
  }

  map(fn) {
    return new Observable((s) => this.subscribe({ next: (v) => s.next(fn(v)), error: s.error, complete: s.complete }).unsubscribe);
  }

  filter(fn) {
    return new Observable((s) => this.subscribe({ next: (v) => { if (fn(v)) s.next(v); }, error: s.error, complete: s.complete }).unsubscribe);
  }

  take(n) {
    return new Observable((s) => {
      if (n <= 0) { s.complete(); return; }
      let count = 0;
      let sub = null;
      let done = false;
      sub = this.subscribe({
        next: (v) => {
          if (done) return;
          s.next(v);
          if (++count >= n) {
            done = true;
            s.complete();
            if (sub) sub.unsubscribe();
          }
        },
        error: s.error,
        complete: s.complete,
      });
      if (done) sub.unsubscribe(); // the source finished n values synchronously
      return () => sub.unsubscribe();
    });
  }
}

