class Scheduler {
  constructor({ maxConcurrent = 3 } = {}) {
    this.maxConcurrent = maxConcurrent;
    this.queues = { high: [], normal: [], low: [] };
    this.running = 0;
    this.started = false;
    this.waiters = [];
  }

  schedule(task, priority = 'normal') {
    if (!this.queues[priority]) throw new Error('Unknown priority: ' + priority);
    return new Promise((resolve, reject) => {
      this.queues[priority].push({ task, resolve, reject });
      if (this.started) this.pump();
    });
  }

  next() {
    for (const p of ['high', 'normal', 'low']) if (this.queues[p].length) return this.queues[p].shift();
    return null;
  }

  pump() {
    while (this.running < this.maxConcurrent) {
      const job = this.next();
      if (!job) break;
      this.running++;
      Promise.resolve()
        .then(job.task)
        .then(job.resolve, job.reject)
        .finally(() => {
          this.running--;
          this.pump();
        });
    }
    const idle = this.running === 0 && !this.queues.high.length && !this.queues.normal.length && !this.queues.low.length;
    if (idle) {
      const ws = this.waiters;
      this.waiters = [];
      ws.forEach((w) => w());
    }
  }

  run() {
    this.started = true;
    const p = new Promise((resolve) => this.waiters.push(resolve));
    this.pump();
    return p;
  }
}

