class Container {
  constructor() {
    this.providers = new Map();
    this.resolving = [];
  }

  register(name, factory) {
    this.providers.set(name, { factory, singleton: false });
    return this;
  }

  singleton(name, factory) {
    this.providers.set(name, { factory, singleton: true, built: false, instance: undefined });
    return this;
  }

  resolve(name) {
    const p = this.providers.get(name);
    if (!p) throw new Error('No provider for "' + name + '"');
    if (p.singleton && p.built) return p.instance;
    if (this.resolving.includes(name)) {
      const cycle = [...this.resolving.slice(this.resolving.indexOf(name)), name].join(' -> ');
      throw new Error('Circular dependency: ' + cycle);
    }
    this.resolving.push(name);
    let instance;
    try {
      instance = p.factory(this);
    } finally {
      this.resolving.pop();
    }
    if (p.singleton) {
      p.instance = instance;
      p.built = true;
    }
    return instance;
  }
}

function createAnalytics({ send, batchSize = 25, flushInterval = 10000, storage = null, retries = 3, retryDelay = 100 } = {}) {
  const KEY = 'analytics-queue';
  const wait = (ms) => new Promise((r) => setTimeout(r, ms));
  let queue = [];
  try { queue = JSON.parse(storage?.getItem(KEY) ?? '[]') || []; } catch { queue = []; }
  let userId = null;
  let running = null;
  let seq = 0;
  const save = () => storage?.setItem(KEY, JSON.stringify(queue));

  const flush = () => {
    if (running) return running;
    if (queue.length === 0) return Promise.resolve();
    const batch = queue.slice();
    running = (async () => {
      for (let attempt = 0; ; attempt++) {
        try {
          await send(batch);
          const sentIds = new Set(batch.map((e) => e.id));
          queue = queue.filter((e) => !sentIds.has(e.id));
          save();
          return;
        } catch (err) {
          if (attempt >= retries) throw err;
          await wait(retryDelay * 2 ** attempt);
        }
      }
    })().finally(() => { running = null; });
    return running;
  };

  const track = (event, props = {}) => {
    queue.push({ id: Date.now().toString(36) + '-' + (seq++), event, props, userId, timestamp: Date.now() });
    save();
    if (queue.length >= batchSize) flush().catch(() => {});
  };

  const identify = (id) => { userId = id; };
  const timer = setInterval(() => { flush().catch(() => {}); }, flushInterval);
  const destroy = () => clearInterval(timer);

  return { track, identify, flush, destroy };
}

function hash32(str) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  h ^= h >>> 16;
  h = Math.imul(h, 0x85ebca6b);
  h ^= h >>> 13;
  h = Math.imul(h, 0xc2b2ae35);
  h ^= h >>> 16;
  return h >>> 0;
}

function bucket(userId, key) {
  return hash32(String(userId) + ':' + key) % 100;
}

const OPS = {
  eq: (a, b) => a === b,
  neq: (a, b) => a !== b,
  in: (a, b) => Array.isArray(b) && b.includes(a),
  gt: (a, b) => a > b,
  lt: (a, b) => a < b,
};

class FeatureFlagClient {
  constructor(flags = []) {
    this.flags = new Map(flags.map((f) => [f.key, f]));
  }

  matches(rule, user, key) {
    if (rule.allow) return user.id !== undefined && rule.allow.includes(user.id);
    if (rule.if) {
      const op = OPS[rule.if.op];
      return !!op && op(user[rule.if.attr], rule.if.value);
    }
    if (typeof rule.percent === 'number') {
      return user.id !== undefined && user.id !== null && bucket(user.id, key) < rule.percent;
    }
    return false;
  }

  getFlag(key, user = {}, fallback) {
    const flag = this.flags.get(key);
    if (!flag) return fallback;
    for (const rule of flag.rules || []) {
      if (this.matches(rule, user, key)) return rule.value;
    }
    return flag.default;
  }

  isEnabled(key, user) {
    return this.getFlag(key, user, false) === true;
  }
}
